def components8(g, bg=None):
    if bg is None:
        bg = Counter([v for row in g for v in row]).most_common(1)[0][0]
    H,W = len(g), len(g[0])
    seen = [[False]*W for _ in g]
    out = []
    for y in range(H):
        for x in range(W):
            if not seen[y][x] and g[y][x]!=bg:
                col = g[y][x]; stack=[(y,x)]; seen[y][x]=True; cells=[]
                while stack:
                    cy,cx = stack.pop(); cells.append((cy,cx))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            ny,nx = cy+dy,cx+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==col:
                                seen[ny][nx]=True; stack.append((ny,nx))
                out.append((col, cells))
    return out

